def largestReorderedSubmatrix(matrix):
    cols = len(matrix[0])
    h = [0] * cols
    best = 0
    for row in matrix:
        for c in range(cols):
            h[c] = h[c] + 1 if row[c] == 1 else 0
        ordered = sorted(h, reverse=True)
        for k, height in enumerate(ordered):
            best = max(best, height * (k + 1))
    return best
